#!/bin/bash
# A minimal reproduction, with a control, of the record docs/designissues/2026-11-09-wasm32-nat-literals.md:
# one Nat literal of 2^31 or more given to two owners, in C generated by Lean on a 64-bit machine.
# Repro: native output "kept [0, 4000000000]"; on wasm32 the kept value is wrong (the literal was freed).
# Control: the same value made at run time; right on both. Needs emcc, Node and a Lean Wasm runtime
# cache ($FACTOIDAL_WASM_RUNTIME_CACHE, see formal/lean4/Wasm/build-wasm.sh).
set -e
HERE=$(cd "$(dirname "$0")" && pwd)
R=${FACTOIDAL_WASM_RUNTIME_CACHE:?Set the Lean Wasm runtime cache path}
OUT=$(mktemp -d)
trap 'rm -rf "$OUT"' EXIT
T=$(cd "$HERE/../../formal/lean4" && lean --print-prefix)
LEAN=$T/bin/lean
F=(-O1 -DNDEBUG -DLEAN_EMSCRIPTEN -fwasm-exceptions -I "$R/wasm-include" -I "$T/include")
for m in Repro Control; do
  "$LEAN" -c "$OUT/$m.c" "$HERE/$m.lean" >/dev/null
  emcc "${F[@]}" -c "$OUT/$m.c" -o "$OUT/$m.o"
  emcc "${F[@]}" -c "$HERE/drv_$m.c" -o "$OUT/drv_$m.o"
  em++ -O1 -DNDEBUG -fwasm-exceptions "$OUT/$m.o" "$OUT/drv_$m.o" "$R"/core-obj/*.o "$R"/rt-obj/*.o -o "$OUT/$m.js" \
    -sALLOW_MEMORY_GROWTH=1 -sSTACK_SIZE=4MB -sENVIRONMENT=node -sASSERTIONS=1 2>&1 | grep -i ' error' || true
  echo "=== $m on wasm32"; node "$OUT/$m.js"
done
